/* ------------------------------------------------------------------------------------------------
 * ShareDialog — the Share surface for one item, data-agnostic: every row, level and link comes
 * in through props and every change goes out through a callback. A `ResponsiveDialog` (`md`, 512px)
 * on wide screens and a bottom sheet on phones, with two tabs:
 *
 *   Share — "Who can see this" first (the summary, closed until asked), an invite row
 *   (`MemberListAdd`: PeoplePicker + the level for the batch + Invite; while people are chosen,
 *   Notify and an optional message), People with access (a `MemberList`: each level a chip menu,
 *   Remove access in the row's ⋯ menu, built-in rows locked with the reason in a tooltip), Space
 *   access, and a footer "Copy link" for the item's own (signed-in) link.
 *
 *   Publish — a "Publish to the web" switch, off by default. Turning it on is the ONLY way the item
 *   is published: no Copy button ever publishes. While on: the public URL, "Copy public link",
 *   Reset, Expires and "Stop publishing" (confirmed).
 * ----------------------------------------------------------------------------------------------*/

/** One row of "People with access". */
export interface ShareEntry {
  /** A stable id — the person's or team's. */
  id: string;
  /** The person or team (`kind: "team"`). */
  person: Person;
  /** Why they have access — "Creator", "Assignee", "Manager of Priya", "via Sales team". @default undefined */
  reason?: React.ReactNode;
  /** Their access level — one of `levels`. */
  level: string;
  /**
   * A built-in row (creator, assignee, manager): the level is shown with a lock, never changed.
   * @default false
   */
  readOnly?: boolean;
  /**
   * Why a built-in (`readOnly`) row's level cannot change, in its tooltip — e.g. "Set by role:
   * Creator". @default "Set by role: {reason}" when `reason` is a string
   */
  lockedReason?: React.ReactNode;
  /** This row is the viewer; "(you)" follows the name. @default false */
  you?: boolean;
}

/** What `onInvite` receives. */
export interface ShareInvite {
  /** The people and teams to add. */
  invitees: PeoplePickerOption[];
  /** The one level given to all of them. */
  level: string;
  /** Notify them. */
  notify: boolean;
  /** The optional note sent with the notification; `""` when none. */
  message: string;
}

/** How long a public link stays live. */
export type ShareLinkExpiry = "never" | "1d" | "7d" | "30d";

/** The item's public (view-only) link, when one is on. */
export interface SharePublicLink {
  /** The link. */
  url: string;
  /** When it stops working. */
  expires: ShareLinkExpiry;
  /**
   * The instant it stops working (ISO), shown beside Expires ("Until Oct 22, 2:30 PM"); `null` or
   * absent for a link that never expires.
   * @default undefined
   */
  expiresAt?: string | null;
}

/** Who in the item's space can open it. */
export interface ShareGeneralAccess {
  /**
   * The item's space. The viewer's own personal space (`access: "personal"`) reads "My space ·
   * Only you and the people above", with no mode or level to change. `null` when the viewer
   * cannot see the space — then `spaceHint` says which kind it is.
   */
  space?: Space | null;
  /**
   * With `space: null`: which kind of space the viewer cannot see holds the item. The row is a
   * plain statement — "In Priya's My space" or "In a private space" — with no mode or level.
   * @default { kind: "private" }
   */
  spaceHint?: SpaceHint | null;
  /** `space` — everyone in the space; `invited` — only people invited. */
  mode: "space" | "invited";
  /**
   * The space members' level while `mode` is `space` — one of `generalLevels`. Omit it when
   * members open the item with their own role in the space: no level shows beside the mode.
   */
  level?: string;
}

/** Every string the dialog renders. */
export interface ShareDialogLabels {
  title: string;
  invitePlaceholder: string;
  /** The invite picker's search field, which lists people and teams. */
  inviteSearchPlaceholder: string;
  inviteEmpty: string;
  inviteLevel: (level: string) => string;
  notify: string;
  messagePlaceholder: string;
  cancel: string;
  peopleHeading: string;
  you: string;
  levelFor: (name: string, level: string) => string;
  generalHeading: string;
  everyoneIn: (space: string) => string;
  onlyInvited: string;
  generalHint: (mode: "space" | "invited", space: string) => string;
  publicHint: string;
  copyPublicLink: string;
  publicLinkField: string;
  resetLink: string;
  resetLinkHint: string;
  /** The reset confirmation's title. */
  resetLinkTitle: string;
  /** The reset confirmation's body. */
  resetLinkBody: string;
  expires: string;
  /** Before the instant a public link expires ("Until"). */
  expiresUntil: string;
  expiry: Record<ShareLinkExpiry, string>;
  copyLink: string;
  copied: string;
  /** The Share tab. */
  shareTab: string;
  /** The Publish tab. */
  publishTab: string;
  /** The invite row's button. */
  invite: string;
  /** The hint beside the footer's Copy link. */
  copyLinkHint: string;
  /** The footer hint while everyone in a named space can open it. */
  copyLinkHintSpace: (space: string) => string;
  /** A personal space's row: "My space". */
  mySpace: string;
  /** A personal space's row hint. */
  mySpaceHint: string;
  /** The space row for a space the viewer cannot see: "In Priya's My space". */
  hiddenSpace: (hint: SpaceHint) => string;
  /** The Share tab's notice while the item is published. */
  publishedNotice: string;
  /** The notice's link to the Publish tab. */
  managePublishing: string;
  /** The Publish switch's label. */
  publishHeading: string;
  /** The Publish switch's hint while off. */
  publishHintOff: string;
  /** The Publish tab's text for a viewer who cannot publish, while it is off. */
  notPublished: string;
  /** The button that turns publishing off. */
  stopPublishing: string;
  /** The Publish tab's footer note while published: what the link never shows. */
  publishPrivateNote: string;
  /** The stop-publishing confirmation's title. */
  stopPublishingTitle: string;
  /** The stop-publishing confirmation's body. */
  stopPublishingBody: string;
  /** A locked built-in row's tooltip, from its reason. */
  lockedReason: (reason: string) => string;
  /** The "Who can see this" section's heading, with the head count once it is known. */
  audienceHeading: (count?: number) => string;
  /** A row's ⋯ menu item that removes its access. @default "Remove access" */
  removeAccess?: string;
  /** A row's ⋯ button. @default (name) => `More for ${name}` */
  moreFor?: (name: string) => string;
}

const defaultLabels: ShareDialogLabels = {
  title: "Share",
  invitePlaceholder: "Add people or teams…",
  inviteSearchPlaceholder: "Search people or teams",
  inviteEmpty: "No people or teams found",
  inviteLevel: (level) => `Access for new people: ${level}`,
  notify: "Notify people",
  messagePlaceholder: "Add a message (optional)",
  cancel: "Cancel",
  peopleHeading: "People with access",
  you: "(you)",
  levelFor: (name, level) => `${name}'s access: ${level}`,
  generalHeading: "Space access",
  everyoneIn: (space) => `Everyone in ${space}`,
  onlyInvited: "Only people invited",
  generalHint: (mode, space) =>
    mode === "space"
      ? `Members of ${space} can find and open it`
      : "Only people with access can open it",
  publicHint: "Anyone with the link can view, without signing in",
  copyPublicLink: "Copy public link",
  publicLinkField: "Public link",
  resetLink: "Reset link",
  resetLinkHint: "Reset link — the current link stops working",
  resetLinkTitle: "Reset the public link?",
  resetLinkBody:
    "The current link stops working at once. Anyone who has it needs the new link.",
  expires: "Expires",
  expiresUntil: "Until",
  expiry: { never: "Never", "1d": "1 day", "7d": "7 days", "30d": "30 days" },
  copyLink: "Copy link",
  copied: "Copied",
  shareTab: "Share",
  publishTab: "Publish",
  invite: "Invite",
  copyLinkHint: "Only people with access can open it",
  copyLinkHintSpace: (space) =>
    `Members of ${space} and people with access can open it`,
  mySpace: "My space",
  mySpaceHint: "Only you and the people above",
  hiddenSpace: (hint) =>
    hint.kind === "personal"
      ? `In ${hint.ownerName}'s My space`
      : "In a private space",
  publishedNotice: "Published to the web",
  managePublishing: "Manage",
  publishHeading: "Publish to the web",
  publishHintOff: "Off — only people with access can open it",
  notPublished: "Not published",
  stopPublishing: "Stop publishing",
  publishPrivateNote: "Comments and version history stay private.",
  stopPublishingTitle: "Stop publishing?",
  stopPublishingBody:
    "The public link stops working at once. People with access can still open it.",
  lockedReason: (reason) => `Set by role: ${reason}`,
  audienceHeading: (count) =>
    count === undefined
      ? "Who can see this"
      : `Who can see this · ${count.toLocaleString()} ${count === 1 ? "person" : "people"}`,
  removeAccess: "Remove access",
  moreFor: (name) => `More for ${name}`,
};

/** Props for `ShareDialog`. */
export interface ShareDialogProps {
  /** Controlled open state. @default undefined */
  open?: boolean;
  /** Called when the dialog opens or closes. @default undefined */
  onOpenChange?: (open: boolean) => void;
  /** Uncontrolled initial open state. @default false */
  defaultOpen?: boolean;
  /** The element that opens the dialog, such as a Share button. @default undefined */
  trigger?: React.ReactElement;
  /** The access levels, most to least, e.g. Full access / Can edit / Can view. */
  levels: readonly PermissionMenuOption[];
  /** The rows of "People with access". */
  people: readonly ShareEntry[];
  /**
   * The viewer may change access: invite, change levels and general access — and, unless
   * `canPublish` says otherwise, the public link. @default true
   */
  canManage?: boolean;
  /**
   * The viewer may publish: turn the public link on, reset it, change its expiry or stop it. A
   * viewer who cannot sees the link to copy while it is published, and "Not published" otherwise.
   * @default canManage
   */
  canPublish?: boolean;
  /** People with access is still loading; skeleton rows show. @default false */
  loading?: boolean;
  /** Finds people and teams to invite — `PeoplePicker`'s `search`. Omit to hide the invite row. @default undefined */
  search?: PeoplePickerSearch;
  /**
   * People and teams already chosen to invite — the dialog opens in invite mode. Reactive: when it
   * changes (compared by id), the chips are replaced with it; edits made since the last change stay
   * until then. @default []
   */
  defaultInvitees?: PeoplePickerOption[];
  /** The level an invite starts at. @default the last of `levels` */
  defaultInviteLevel?: string;
  /**
   * Sends an invite; the chips clear when it resolves. Resolve `false` (or reject) to keep them
   * for a retry — the host shows its own error. @default undefined
   */
  onInvite?: (invite: ShareInvite) => void | boolean | Promise<void | boolean>;
  /** Changes one row's level. @default undefined */
  onLevelChange?: (id: string, level: string) => void;
  /** Removes one row's access; adds "Remove access" to its menu. @default undefined */
  onRemove?: (id: string) => void;
  /** The item's space and who in it can open the item. Omit to hide General access. @default undefined */
  generalAccess?: ShareGeneralAccess;
  /** The levels a whole space may get. @default levels */
  generalLevels?: readonly PermissionMenuOption[];
  /** General access's level shows as text even for a manager, who can still change the mode. @default false */
  generalLevelReadOnly?: boolean;
  /** Changes General access. @default undefined */
  onGeneralAccessChange?: (next: {
    mode: "space" | "invited";
    /** The space's level — `""` while `generalAccess.level` is omitted (members use their own role). */
    level: string;
  }) => void;
  /** Offer the public link row at all. @default true */
  publicLinkAvailable?: boolean;
  /** The public link while it is on; `null` while it is off. @default null */
  publicLink?: SharePublicLink | null;
  /**
   * Turns the public link on — called ONLY by the Publish tab's switch, never by a Copy button.
   * A returned URL is ignored (nothing is copied as a side effect). @default undefined
   */
  onCreatePublicLink?: () => Promise<string | void> | string | void;
  /** Replaces the public link with a new one. @default undefined */
  onResetPublicLink?: () => void | Promise<void>;
  /** Changes when the public link expires. @default undefined */
  onPublicLinkExpiresChange?: (expires: ShareLinkExpiry) => void;
  /** Turns the public link off. @default undefined */
  onStopPublicLink?: () => void | Promise<void>;
  /**
   * Asked before the Publish switch turns the link on — confirm what it will expose ("Publish 13
   * pages?") and resolve `false` to leave it off. Without it, the switch publishes at once.
   * @default undefined
   */
  onPublishRequest?: () => boolean | Promise<boolean>;
  /**
   * What the public link exposes, under the Publish switch — "Anyone with the link can view this
   * page and 12 pages inside, without signing in." Replaces `labels.publicHint` (on) and
   * `labels.publishHintOff` (off) for a viewer who can publish, and wraps rather than truncates.
   * @default undefined
   */
  publishExposure?: React.ReactNode;
  /**
   * "Who can see this": the summary at the top of the Share tab, a collapsible closed at first —
   * load its rows in `onAudienceOpenChange`. Its heading is `labels.audienceHeading(audienceCount)`.
   * @default undefined
   */
  audience?: React.ReactNode;
  /** The head count in the "Who can see this" heading, once known. @default undefined */
  audienceCount?: number;
  /** Called when "Who can see this" opens or closes — load its rows on first open. @default undefined */
  onAudienceOpenChange?: (open: boolean) => void;
  /** A public-link change is in flight; its controls wait. @default false */
  publicLinkPending?: boolean;
  /**
   * More settings for the public link while it is on (what the link shows, say), for a viewer who
   * can publish: rows of the Publish tab's settings grid under Expires, each a label then its
   * control (two children, in a fragment), so every label and control lines up. @default undefined
   */
  publicLinkOptions?: React.ReactNode;
  /** The item's own link, for Copy link in the footer. Omit to hide Copy link. @default undefined */
  linkUrl?: string;
  /** A muted note above the footer, such as "Admins can view this space." @default undefined */
  footerNote?: React.ReactNode;
  /** Override any rendered string. @default {} */
  labels?: Partial<ShareDialogLabels>;
  /** The tab the dialog opens on — `publish` when opened from a "Published" indicator. @default "share" */
  defaultTab?: "share" | "publish";
  /**
   * Optional help nodes (an info button or a "Learn more" link) placed right after the People
   * with access heading, the Space access heading and the Publish switch's label.
   * @default {}
   */
  hints?: {
    people?: React.ReactNode;
    general?: React.ReactNode;
    publish?: React.ReactNode;
  };
}

/** A line tab whose underline and label both start where the dialog's content does. */
const LINE_TAB = "flex-none border-x-0 px-0";

/**
 * The inactive panel (and the Share footer on the Publish tab) hides with `visibility`, not
 * `display`, so its box keeps the dialog's height. `visibility` is animatable, and every control
 * with upstream's `transition-all` (Button, Switch, Select trigger…) inherits it and would stay
 * painted for its transition's length: a Switch over the Invite button, or Invite over the
 * Publish row, for a beat after every tab change. Descendants of a hidden box therefore carry no
 * transition, so they hide in the same frame; showing is immediate either way.
 */
const HIDDEN_BOX = "data-hidden:invisible data-hidden:**:transition-none";

const EXPIRIES: readonly ShareLinkExpiry[] = ["never", "1d", "7d", "30d"];

function SectionHeading({
  children,
  hint,
}: {
  children: React.ReactNode;
  hint?: React.ReactNode;
}) {
  const heading = (
    <h3 className="text-xs font-medium text-muted-foreground">{children}</h3>
  );
  if (!hint) return heading;
  return (
    <div className="flex items-center gap-1">
      {heading}
      {hint}
    </div>
  );
}

/** A 32px muted tile holding an icon, beside a row's text. */
function IconTile({ children }: { children: React.ReactNode }) {
  return (
    <span
      aria-hidden
      className="flex size-8 shrink-0 items-center justify-center rounded-md bg-muted text-muted-foreground [&_svg]:size-4"
    >
      {children}
    </span>
  );
}

/**
 * `ShareDialog` — share one item with people and teams, see who in its space can open it, and
 * publish it to the web from its own tab.
 *
 * @example
 * <ShareDialog
 *   trigger={<Button variant="outline">Share</Button>}
 *   levels={LEVELS}
 *   people={entries}
 *   search={searchDirectory}
 *   onInvite={invite}
 *   onLevelChange={setLevel}
 *   onRemove={removeAccess}
 *   onCreatePublicLink={publish}
 *   defaultTab="share"
 * />
 */
export function ShareDialog({
  open: openProp,
  onOpenChange,
  defaultOpen = false,
  trigger,
  levels,
  people,
  canManage = true,
  canPublish = canManage,
  loading = false,
  search,
  defaultInvitees = [],
  defaultInviteLevel,
  onInvite,
  onLevelChange,
  onRemove,
  generalAccess,
  generalLevels = levels,
  generalLevelReadOnly = false,
  onGeneralAccessChange,
  publicLinkAvailable = true,
  publicLink = null,
  onCreatePublicLink,
  onResetPublicLink,
  onPublicLinkExpiresChange,
  onStopPublicLink,
  onPublishRequest,
  publishExposure,
  audience,
  audienceCount,
  onAudienceOpenChange,
  publicLinkPending = false,
  publicLinkOptions,
  linkUrl,
  footerNote,
  labels: labelsProp,
  defaultTab = "share",
  hints = {},
}: ShareDialogProps) {
  const labels = { ...defaultLabels, ...labelsProp };

  const [openState, setOpenState] = React.useState(defaultOpen);
  const open = openProp ?? openState;
  const setOpen = (next: boolean) => {
    setOpenState(next);
    onOpenChange?.(next);
  };
  const [chosenTab, setTab] = React.useState<"share" | "publish">(defaultTab);
  // Each opening starts on the tab the caller asked for.
  const [wasOpen, setWasOpen] = React.useState(open);
  if (wasOpen !== open) {
    setWasOpen(open);
    if (open) setTab(defaultTab);
  }
  // Without public links there is no Publish tab: Share shows, whatever was chosen.
  const tab = publicLinkAvailable ? chosenTab : "share";

  const [invitees, setInvitees] =
    React.useState<PeoplePickerOption[]>(defaultInvitees);
  // Re-sync the chips when `defaultInvitees` changes — by ids, so a fresh array with the same
  // people each render is not a change and never clobbers what the viewer has edited since.
  const defaultInviteesKey = defaultInvitees
    .map((option) => option.id)
    .join("\u0000");
  const [syncedInviteesKey, setSyncedInviteesKey] =
    React.useState(defaultInviteesKey);
  if (syncedInviteesKey !== defaultInviteesKey) {
    setSyncedInviteesKey(defaultInviteesKey);
    setInvitees(defaultInvitees);
  }
  const [inviteLevel, setInviteLevel] = React.useState(
    defaultInviteLevel ?? levels.at(-1)?.value ?? "",
  );
  const [notify, setNotify] = React.useState(true);
  const [message, setMessage] = React.useState("");
  const [inviting, setInviting] = React.useState(false);
  const [confirmStop, setConfirmStop] = React.useState(false);
  const [confirmReset, setConfirmReset] = React.useState(false);
  const publishLabelId = React.useId();
  const publishTabRef = React.useRef<HTMLButtonElement>(null);
  const panelsRef = React.useRef<HTMLDivElement>(null);
  // The two panels share one scrolling body: a new tab starts at its top, so a list scrolled on
  // Share never leaves Publish's controls above the viewport.
  React.useLayoutEffect(() => {
    panelsRef.current?.parentElement?.scrollTo({ top: 0 });
  }, [tab]);
  const inviteMode = canManage && invitees.length > 0;

  const resetInvite = () => {
    setInvitees([]);
    setMessage("");
    setNotify(true);
  };

  const sendInvite = async () => {
    if (!onInvite || invitees.length === 0) return;
    setInviting(true);
    try {
      const saved = await onInvite({
        invitees,
        level: inviteLevel,
        notify,
        message,
      });
      if (saved !== false) resetInvite();
    } catch {
      // The host reports the error; the chips stay for a retry.
    } finally {
      setInviting(false);
    }
  };

  const levelLabel = (value: string, options = levels) =>
    options.find((option) => option.value === value)?.label ?? value;

  // ---- Share tab --------------------------------------------------------------------------------

  const inviteRow =
    canManage && search ? (
      <MemberListAdd
        data-slot="share-invite-row"
        picker={
          <PeoplePicker
            multiple
            value={invitees}
            onValueChange={setInvitees}
            search={search}
            placeholder={labels.invitePlaceholder}
            searchPlaceholder={labels.inviteSearchPlaceholder}
            emptyText={labels.inviteEmpty}
            aria-label={labels.invitePlaceholder.replace(/…$/, "")}
            disabled={inviting}
          />
        }
        roles={levels}
        role={inviteLevel}
        onRoleChange={setInviteLevel}
        roleLabel={(label) => labels.inviteLevel(label)}
        onAdd={sendInvite}
        adding={inviting}
        disabled={invitees.length === 0}
        addLabel={labels.invite}
      />
    ) : null;

  const inviteSection = (
    <div data-slot="share-invite" className="flex flex-col gap-3">
      <label className="flex items-center gap-2 text-sm">
        <Checkbox
          checked={notify}
          onCheckedChange={(checked) => setNotify(checked === true)}
        />
        {labels.notify}
      </label>
      {notify ? (
        <Textarea
          value={message}
          onChange={(event) => setMessage(event.target.value)}
          placeholder={labels.messagePlaceholder}
          aria-label={labels.messagePlaceholder.replace(/ \(optional\)$/, "")}
          rows={3}
        />
      ) : null}
    </div>
  );

  const members: MemberListMember[] = people.map((entry) => ({
    id: entry.id,
    person: entry.person,
    description: entry.reason,
    role: entry.level,
    locked: entry.readOnly,
    lockedReason:
      entry.lockedReason ??
      (typeof entry.reason === "string"
        ? labels.lockedReason(entry.reason)
        : undefined),
    you: entry.you,
  }));

  const peopleSection = (
    <section data-slot="share-people" className="flex flex-col gap-1">
      <SectionHeading hint={hints.people}>
        {labels.peopleHeading}
      </SectionHeading>
      <MemberList
        members={members}
        roles={levels}
        canManage={canManage}
        loading={loading}
        empty={null}
        onRoleChange={onLevelChange}
        onRemove={onRemove}
        labels={{
          list: labels.peopleHeading,
          you: labels.you,
          roleFor: labels.levelFor,
          more: labels.moreFor ?? defaultLabels.moreFor,
          remove: labels.removeAccess ?? defaultLabels.removeAccess,
        }}
      />
    </section>
  );

  const space = generalAccess?.space ?? null;
  // A statement, not a control: the viewer's own My space, or a space they cannot see.
  const statement: { tile: React.ReactNode; text: React.ReactNode } | null =
    !generalAccess
      ? null
      : !space
        ? {
            tile: (
              <IconGlyph
                fallback={
                  generalAccess.spaceHint?.kind === "personal" ? (
                    <UserLock />
                  ) : (
                    <Lock />
                  )
                }
              />
            ),
            text: labels.hiddenSpace(
              generalAccess.spaceHint ?? { kind: "private" },
            ),
          }
        : space.access === "personal"
          ? {
              tile: <UserLock />,
              text: (
                <>
                  {labels.mySpace}
                  <span className="text-muted-foreground">
                    {" · "}
                    {labels.mySpaceHint}
                  </span>
                </>
              ),
            }
          : null;
  const generalSection = !generalAccess ? null : (
    <section data-slot="share-general" className="flex flex-col gap-2">
      <SectionHeading hint={hints.general}>
        {labels.generalHeading}
      </SectionHeading>
      {statement ? (
        <div className="flex min-w-0 items-center gap-2">
          <IconTile>{statement.tile}</IconTile>
          <span className="min-w-0 flex-1 truncate text-sm">
            {statement.text}
          </span>
        </div>
      ) : space ? (
        <div className="flex min-w-0 items-center gap-2">
          <IconGlyph
            fallback={
              space.icon ?? Array.from(space.name.trim())[0]?.toUpperCase()
            }
            hue={space.hue}
            size="default"
          />
          <div className="flex min-w-0 flex-1 flex-col items-start">
            {canManage ? (
              <Select
                items={[
                  { value: "space", label: labels.everyoneIn(space.name) },
                  { value: "invited", label: labels.onlyInvited },
                ]}
                value={generalAccess.mode}
                onValueChange={(mode) =>
                  onGeneralAccessChange?.({
                    mode: mode as "space" | "invited",
                    level: generalAccess.level ?? "",
                  })
                }
              >
                {/* The quiet property-pill form (RecordChip's ghost): no border, a tint and a
                    ▾ fading in on hover, focus and while open; the text stays where the hint's
                    starts. */}
                <SelectTrigger
                  variant="ghost"
                  size="sm"
                  aria-label={labels.generalHeading}
                  className="-ms-1.5 w-auto max-w-full gap-2 border-0 py-0 ps-1.5 pe-1.5 text-sm hover:bg-muted aria-expanded:bg-muted focus-visible:bg-muted data-[size=sm]:h-6 data-[size=sm]:rounded-md dark:hover:bg-muted/50 dark:aria-expanded:bg-muted/50 [&>svg]:-ms-1 [&>svg]:size-3.5 [&>svg]:opacity-0 [&>svg]:transition-opacity hover:[&>svg]:opacity-100 focus-visible:[&>svg]:opacity-100 aria-expanded:[&>svg]:opacity-100"
                >
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="space">
                    {labels.everyoneIn(space.name)}
                  </SelectItem>
                  <SelectItem value="invited">{labels.onlyInvited}</SelectItem>
                </SelectContent>
              </Select>
            ) : (
              <span className="truncate text-sm">
                {generalAccess.mode === "space"
                  ? labels.everyoneIn(space.name)
                  : labels.onlyInvited}
              </span>
            )}
            <span className="truncate text-xs text-muted-foreground">
              {labels.generalHint(generalAccess.mode, space.name)}
            </span>
          </div>
          {generalAccess.mode === "space" && generalAccess.level != null ? (
            <PermissionMenu
              variant="chip"
              value={generalAccess.level}
              options={generalLevels}
              readOnly={!canManage || generalLevelReadOnly}
              onValueChange={(level) =>
                onGeneralAccessChange?.({ mode: "space", level })
              }
              aria-label={labels.levelFor(
                labels.everyoneIn(space.name),
                levelLabel(generalAccess.level, generalLevels),
              )}
            />
          ) : null}
        </div>
      ) : null}
    </section>
  );

  // While published, the Share tab says so in one line, with a way to the Publish tab.
  const publishedNotice =
    publicLinkAvailable && publicLink ? (
      <p
        data-slot="share-published-notice"
        className="flex min-w-0 items-center gap-2 text-sm text-muted-foreground"
      >
        <GlobeIcon aria-hidden className="size-4 shrink-0" />
        <span className="min-w-0 truncate">{labels.publishedNotice}</span>
        <Button
          variant="link"
          size="xs"
          className="ms-auto h-auto shrink-0 px-0"
          onClick={() => {
            // Manage unmounts with the Share tab: hand focus to the Publish trigger first.
            publishTabRef.current?.focus();
            setTab("publish");
          }}
        >
          {labels.managePublishing}
        </Button>
      </p>
    ) : null;

  // "Who can see this": closed at first, its rows the host's (loaded when it opens).
  const audienceSection =
    audience !== undefined ? (
      <Collapsible
        data-slot="share-audience"
        onOpenChange={(open) => onAudienceOpenChange?.(open)}
        className="flex flex-col gap-2"
      >
        <CollapsibleTrigger
          render={
            <Button
              variant="ghost"
              size="sm"
              className={cn(
                "-mx-2 w-[calc(100%+var(--spacing)*4)] justify-between px-2 text-xs font-medium text-muted-foreground hover:text-foreground aria-expanded:text-foreground [&[data-panel-open]>svg]:rotate-180",
                disclosureTriggerClasses,
              )}
            />
          }
        >
          <span className="min-w-0 truncate">
            {labels.audienceHeading(audienceCount)}
          </span>
          <ChevronDown
            aria-hidden
            className="transition-transform duration-150"
          />
        </CollapsibleTrigger>
        <CollapsibleContent data-slot="share-audience-content">
          {audience}
        </CollapsibleContent>
      </Collapsible>
    ) : null;

  const shareBody = (
    <div data-slot="share-dialog-body" className="flex flex-col gap-4 pb-1">
      {audienceSection}
      {inviteRow}
      {inviteMode ? (
        inviteSection
      ) : (
        <>
          {peopleSection}
          {generalSection}
          {publishedNotice}
          {footerNote ? (
            <p className="text-xs text-muted-foreground">{footerNote}</p>
          ) : null}
        </>
      )}
    </div>
  );

  // ---- Publish tab ------------------------------------------------------------------------------

  const publishBody = (
    <div data-slot="share-public-link" className="flex flex-col gap-3 pb-1">
      <div className="flex min-w-0 items-center gap-2">
        <IconTile>
          <GlobeIcon />
        </IconTile>
        <div className="flex min-w-0 flex-1 flex-col">
          <span className="flex min-w-0 items-center gap-1">
            <span id={publishLabelId} className="truncate text-sm">
              {labels.publishHeading}
            </span>
            {hints.publish}
          </span>
          {publishExposure !== undefined && (publicLink || canPublish) ? (
            <span
              data-slot="share-publish-exposure"
              className="text-xs text-pretty text-muted-foreground"
            >
              {publishExposure}
            </span>
          ) : (
            // Wraps, never truncated: at 320px the whole hint still reads.
            <span className="text-xs text-pretty text-muted-foreground">
              {publicLink
                ? labels.publicHint
                : canPublish
                  ? labels.publishHintOff
                  : labels.notPublished}
            </span>
          )}
        </div>
        {canPublish ? (
          <Switch
            aria-labelledby={publishLabelId}
            checked={publicLink !== null}
            disabled={publicLinkPending}
            onCheckedChange={(checked) => {
              if (!checked) {
                setConfirmStop(true);
                return;
              }
              // The host may confirm first (what the link exposes); a `false` leaves it off.
              void (async () => {
                if (onPublishRequest && !(await onPublishRequest())) return;
                await onCreatePublicLink?.();
              })();
            }}
          />
        ) : null}
      </div>
      {publicLink ? (
        <div className="flex flex-col gap-3">
          <div className="flex min-w-0 items-center gap-2">
            <InputGroup className="min-w-0 flex-1">
              <InputGroupInput
                readOnly
                value={publicLink.url}
                aria-label={labels.publicLinkField}
                onFocus={(event) => event.currentTarget.select()}
              />
              {canPublish ? (
                <InputGroupAddon align="inline-end">
                  <Tooltip>
                    <TooltipTrigger
                      render={
                        <InputGroupButton
                          size="icon-xs"
                          aria-label={labels.resetLink}
                          disabled={publicLinkPending}
                          // Asks first, like Stop publishing: the live link stops at once.
                          onClick={() => setConfirmReset(true)}
                        />
                      }
                    >
                      <RotateCcwIcon />
                    </TooltipTrigger>
                    <TooltipContent>{labels.resetLinkHint}</TooltipContent>
                  </Tooltip>
                </InputGroupAddon>
              ) : null}
            </InputGroup>
            <CopyButton
              value={publicLink.url}
              showLabel
              variant="outline"
              size="default"
              copyLabel={labels.copyPublicLink}
              copiedLabel={labels.copied}
            />
          </div>
          {canPublish ? (
            // The link's settings as one grid: each label beside its control, the host's rows
            // (`publicLinkOptions`) lined up with Expires.
            <div
              data-slot="share-public-link-options"
              className="grid grid-cols-[auto_minmax(0,1fr)] items-center justify-items-start gap-x-3 gap-y-2"
            >
              <span className="text-sm text-muted-foreground">
                {labels.expires}
              </span>
              <Select
                items={EXPIRIES.map((value) => ({
                  value,
                  label: labels.expiry[value],
                }))}
                value={publicLink.expires}
                onValueChange={(value) =>
                  onPublicLinkExpiresChange?.(value as ShareLinkExpiry)
                }
                disabled={publicLinkPending}
              >
                <SelectTrigger
                  size="sm"
                  aria-label={labels.expires}
                  className="w-fit"
                >
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {EXPIRIES.map((value) => (
                    <SelectItem key={value} value={value}>
                      {labels.expiry[value]}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              {publicLink.expiresAt && publicLink.expires !== "never" ? (
                // The instant it lapses, in the viewer's zone (a preset alone says nothing once
                // time has passed).
                <span
                  data-slot="share-public-link-expires-at"
                  className="col-start-2 -mt-1 text-xs text-muted-foreground"
                >
                  {labels.expiresUntil}{" "}
                  <DateTime
                    date={publicLink.expiresAt}
                    variant="datetime"
                    options={{ relativeDay: false }}
                    title={false}
                  />
                </span>
              ) : null}
              {publicLinkOptions}
            </div>
          ) : null}
        </div>
      ) : null}
      <AlertDialog open={confirmReset} onOpenChange={setConfirmReset}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>{labels.resetLinkTitle}</AlertDialogTitle>
            <AlertDialogDescription>
              {labels.resetLinkBody}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>{labels.cancel}</AlertDialogCancel>
            <AlertDialogAction
              variant="destructive"
              disabled={publicLinkPending}
              onClick={() => {
                // Once per confirmation: the button stays mounted while the dialog closes.
                if (!confirmReset) return;
                setConfirmReset(false);
                void onResetPublicLink?.();
              }}
            >
              {labels.resetLink}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
      <AlertDialog open={confirmStop} onOpenChange={setConfirmStop}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>{labels.stopPublishingTitle}</AlertDialogTitle>
            <AlertDialogDescription>
              {labels.stopPublishingBody}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>{labels.cancel}</AlertDialogCancel>
            <AlertDialogAction
              variant="destructive"
              disabled={publicLinkPending}
              onClick={() => {
                // Once per confirmation: the button stays mounted while the dialog closes.
                if (!confirmStop) return;
                setConfirmStop(false);
                void onStopPublicLink?.();
              }}
            >
              {labels.stopPublishing}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );

  // The Publish tab's footer while published: what stays private, and Stop publishing.
  const publishFooter =
    publicLinkAvailable && publicLink && canPublish ? (
      <div
        data-slot="share-publish-footer"
        className="flex w-full flex-wrap items-center justify-between gap-2"
      >
        <span className="text-xs text-muted-foreground">
          {labels.publishPrivateNote}
        </span>
        <Button
          variant="destructive"
          disabled={publicLinkPending}
          onClick={() => setConfirmStop(true)}
        >
          {labels.stopPublishing}
        </Button>
      </div>
    ) : null;
  // The Share tab's footer. It keeps its box on the Publish tab (hidden and inert there), so the
  // dialog does not change height when the tabs switch.
  const footer = inviteMode ? (
    <Button variant="secondary" onClick={resetInvite} disabled={inviting}>
      {labels.cancel}
    </Button>
  ) : linkUrl ? (
    <div
      data-slot="share-copy-link"
      className="flex w-full flex-wrap items-center justify-between gap-2"
    >
      <span className="text-xs text-muted-foreground">
        {generalAccess?.mode === "space" &&
        generalAccess.space &&
        generalAccess.space.access !== "personal"
          ? labels.copyLinkHintSpace(generalAccess.space.name)
          : labels.copyLinkHint}
      </span>
      <CopyButton
        value={linkUrl}
        showLabel
        variant="outline"
        size="default"
        copyLabel={labels.copyLink}
        copiedLabel={labels.copied}
      />
    </div>
  ) : null;

  return (
    <ResponsiveDialog open={open} onOpenChange={setOpen}>
      {trigger ? <ResponsiveDialogTrigger render={trigger} /> : null}
      <ResponsiveDialogContent size="md" data-share-dialog="">
        <ResponsiveDialogHeader>
          <ResponsiveDialogTitle>{labels.title}</ResponsiveDialogTitle>
        </ResponsiveDialogHeader>
        <Tabs
          value={tab}
          onValueChange={(next) => setTab(next as "share" | "publish")}
          className="flex min-h-0 flex-1 flex-col gap-4"
        >
          {publicLinkAvailable ? (
            // Upstream's line list pads its triggers 3px + 1px border + 6px in from the list edge.
            // Here the underline and the label start ON the content edge, like the title and the
            // rows below: no list padding, no trigger padding, a 16px gap between the tabs. The
            // phone sheet's content has no padding of its own, so the list takes the 16px inset
            // its header and body carry. Two tabs never scroll, so the list does not clip: a
            // focused tab's forced-colours outline keeps its leading side (in RTL too).
            <TabsList
              variant="line"
              overflow="visible"
              className="-mt-1 justify-start gap-4 px-0 in-data-[slot=sheet-content]:mx-4"
            >
              <TabsTrigger value="share" className={LINE_TAB}>
                {labels.shareTab}
              </TabsTrigger>
              <TabsTrigger
                ref={publishTabRef}
                value="publish"
                className={LINE_TAB}
              >
                {labels.publishTab}
                {publicLink ? (
                  <GlobeIcon
                    aria-hidden
                    data-slot="share-published-dot"
                    className="size-3 text-muted-foreground"
                  />
                ) : null}
              </TabsTrigger>
            </TabsList>
          ) : null}
          <ResponsiveDialogBody>
            {/* Both panels stay mounted in ONE grid cell, the inactive one invisible and inert, so
                the body is always as tall as the taller panel and switching tabs never resizes
                the dialog or the sheet. The cell's track may shrink below its content's widest
                line (`grid-cols-1`): at 320px the rows wrap instead of running off the sheet. */}
            <div
              ref={panelsRef}
              data-slot="share-panels"
              className="grid grid-cols-1"
            >
              <TabsContent
                value="share"
                keepMounted
                hidden={false}
                className={`col-start-1 row-start-1 ${HIDDEN_BOX}`}
              >
                {shareBody}
              </TabsContent>
              {publicLinkAvailable ? (
                <TabsContent
                  value="publish"
                  keepMounted
                  hidden={false}
                  className={`col-start-1 row-start-1 ${HIDDEN_BOX}`}
                >
                  {publishBody}
                </TabsContent>
              ) : null}
            </div>
          </ResponsiveDialogBody>
        </Tabs>
        {footer || publishFooter ? (
          // One footer box, two layers in one grid cell: the Share tab's and the Publish tab's
          // (Stop publishing), so switching tabs never resizes the dialog.
          <ResponsiveDialogFooter className="grid grid-cols-1">
            <div
              data-hidden={tab === "share" ? undefined : ""}
              inert={tab !== "share"}
              className={`col-start-1 row-start-1 flex w-full min-w-0 justify-end ${HIDDEN_BOX}`}
            >
              {footer}
            </div>
            {publishFooter ? (
              <div
                data-hidden={tab === "publish" ? undefined : ""}
                inert={tab !== "publish"}
                className={`col-start-1 row-start-1 flex w-full min-w-0 ${HIDDEN_BOX}`}
              >
                {publishFooter}
              </div>
            ) : null}
          </ResponsiveDialogFooter>
        ) : null}
      </ResponsiveDialogContent>
    </ResponsiveDialog>
  );
}
